<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Check, ChevronRight, Copy, ExternalLink, RefreshCw } from 'lucide-vue-next'
import type { ProductWritingBlock, ProductWritingBlockEvidence, ProductWritingDocument, ProductWritingProject } from '@/types/product'

const props = defineProps<{ project: ProductWritingProject; document: ProductWritingDocument; saveState: 'idle' | 'saving' | 'saved' | 'offline' | 'conflict'; activeBlockId: string | null; evidence: ProductWritingBlockEvidence | null; evidenceLoading: boolean }>()
const emit = defineEmits<{ edit: [block: ProductWritingBlock, content: string, immediate?: boolean]; evidence: [block: ProductWritingBlock]; closeEvidence: []; regenerate: []; copy: [] }>()
const drafts = ref<Record<string, string>>({})
watch(() => props.document, (document) => { drafts.value = Object.fromEntries(document.sections.flatMap((section) => section.blocks.map((block) => [block.id, block.content]))) }, { immediate: true })
const reviewItems = computed(() => props.project.reviewItems.filter((item) => item.status === 'open'))
function text(block: ProductWritingBlock) { return drafts.value[block.id] ?? block.content }
function edit(block: ProductWritingBlock, event: Event, immediate = false) { drafts.value[block.id] = (event.target as HTMLElement).innerText; emit('edit', block, drafts.value[block.id], immediate) }
function citationCount(block: ProductWritingBlock) { return block.evidenceRefs.length + block.sourceRefs.length }
</script>

<template>
  <div class="article-workspace">
    <main class="article-column">
      <header class="article-toolbar"><div><span class="eyebrow">文章草稿 · 需人工确认</span><h1>{{ document.title }}</h1><p>{{ document.summary }}</p></div><div class="toolbar-actions"><span class="save-status" :class="saveState"><Check v-if="saveState === 'saved'" :size="13" aria-hidden="true" />{{ saveState === 'saving' ? '保存中…' : saveState === 'saved' ? '已保存' : saveState === 'conflict' ? '保存冲突' : saveState === 'offline' ? '待重试' : '自动保存' }}</span><button class="icon-button" type="button" title="复制 Markdown" aria-label="复制 Markdown" @click="emit('copy')"><Copy :size="15" aria-hidden="true" /></button><button class="secondary-button" type="button" @click="emit('regenerate')"><RefreshCw :size="13" aria-hidden="true" />重新生成</button></div></header>
      <div v-if="reviewItems.length" class="review-strip" role="status"><strong>{{ reviewItems.length }} 个地方需要复核</strong><span>{{ reviewItems[0]?.message }}</span></div>
      <article class="article-paper"><p class="article-lede">这是一篇从真实实践记录整理出的工程复盘。文中的引用保留了当时的实验与参考依据。</p><section v-for="section in document.sections" :key="section.id" class="article-section"><h2>{{ section.title }}</h2><div v-for="block in section.blocks" :key="block.id" class="article-block-row" :class="{ active: activeBlockId === block.id }"><div class="article-block" contenteditable="true" role="textbox" :aria-label="`${section.title}段落`" spellcheck="false" @input="edit(block, $event)" @blur="edit(block, $event, true)">{{ text(block) }}</div><div class="citation-tools" v-if="citationCount(block)"><button v-for="(ref, index) in [...block.evidenceRefs, ...block.sourceRefs]" :key="ref" class="citation" type="button" :class="{ active: activeBlockId === block.id }" :aria-label="`查看第 ${index + 1} 条引用`" @click="emit('evidence', block)">[{{ index + 1 }}]</button><button class="citation-more" type="button" :aria-label="`查看 ${citationCount(block)} 条证据`" @click="emit('evidence', block)"><ChevronRight :size="12" aria-hidden="true" /></button></div></div></section><footer><span>知行工程实践复盘</span><span>修改会自动保存，不会自动发布</span></footer></article>
    </main>
    <aside v-if="activeBlockId" class="evidence-rail" aria-label="当前段落的证据"><header><div><span class="eyebrow">证据回查</span><h2>这段内容依据什么</h2></div><button class="close-button" type="button" aria-label="关闭证据栏" @click="emit('closeEvidence')">×</button></header><div v-if="evidenceLoading" class="rail-state">正在读取引用…</div><template v-else-if="evidence"><p class="rail-context">当前段落的主引用与关联依据</p><article v-for="reference in evidence.references" :key="`${reference.refType}:${reference.refId}`" class="reference-card"><div class="reference-type">{{ reference.role === 'source' ? '知乎 · 原理参考' : 'Lab · 实验记录' }}</div><h3>{{ reference.title }}</h3><p>{{ reference.content }}</p><div class="reference-meta"><span>{{ reference.verificationStatus }}</span><a v-if="reference.url" :href="reference.url" target="_blank" rel="noreferrer"><ExternalLink :size="11" aria-hidden="true" />查看来源</a></div></article><div v-if="!evidence.references.length" class="rail-state">这段暂时没有可读取的引用。</div></template></aside>
  </div>
</template>

<style scoped>
.article-workspace { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 22px; align-items: start; }.article-column { min-width: 0; }.article-toolbar { display: flex; justify-content: space-between; align-items: start; gap: 20px; padding: 22px 0 18px; border-bottom: 1px solid var(--line); }.article-toolbar h1 { margin: 6px 0 0; color: var(--ink); font: 400 27px/1.25 var(--serif); }.article-toolbar p { max-width: 660px; margin: 8px 0 0; color: var(--muted); font-size: 11px; line-height: 1.55; }.toolbar-actions { display: flex; align-items: center; gap: 9px; flex: 0 0 auto; }.toolbar-actions button { display: inline-flex; align-items: center; gap: 5px; white-space: nowrap; }.icon-button { display: grid; place-items: center; width: 32px; height: 32px; border: 1px solid var(--line); background: transparent; color: var(--blue); }.save-status { display: inline-flex; align-items: center; gap: 4px; color: var(--muted); font: 9px var(--mono); white-space: nowrap; }.save-status.saved { color: var(--green); }.save-status.conflict, .save-status.offline { color: var(--red); }.review-strip { display: flex; gap: 10px; align-items: baseline; margin-top: 14px; padding: 10px 12px; border-left: 2px solid var(--orange); background: var(--orange-soft); color: var(--muted); font-size: 10px; }.review-strip strong { color: #94623c; }.article-paper { max-width: 780px; margin: 24px auto 50px; padding: 40px 54px 48px; background: #fff; box-shadow: 0 9px 26px rgb(33 43 40 / 8%); color: #29312f; }.article-lede { margin: 0 0 32px; color: #6a746e; font-size: 13px; line-height: 1.8; }.article-section { margin-top: 30px; }.article-section h2 { margin: 0 0 12px; color: #26322f; font: 400 20px/1.35 var(--serif); }.article-block-row { position: relative; display: block; margin: 0 -10px; padding: 3px 38px 3px 10px; border-left: 2px solid transparent; }.article-block-row:hover, .article-block-row.active { border-left-color: var(--blue); background: var(--blue-soft); }.article-block { min-height: 24px; outline: 0; white-space: pre-wrap; color: #53605a; font-size: 13px; line-height: 1.9; }.citation-tools { position: absolute; top: 5px; right: 7px; display: flex; align-items: center; gap: 2px; }.citation, .citation-more { border: 0; background: transparent; color: var(--blue); cursor: pointer; font: 9px var(--mono); }.citation:hover, .citation.active, .citation-more:hover { color: var(--blue-deep); text-decoration: underline; }.citation-more { display: grid; place-items: center; padding: 1px; }.article-paper footer { display: flex; justify-content: space-between; gap: 12px; margin-top: 42px; padding-top: 14px; border-top: 1px solid var(--line); color: var(--muted); font: 9px var(--mono); }.evidence-rail { position: sticky; top: 20px; max-height: calc(100dvh - 40px); overflow-y: auto; border-top: 2px solid var(--blue); background: var(--paper-muted); }.evidence-rail > header { display: flex; justify-content: space-between; gap: 12px; padding: 16px 16px 13px; border-bottom: 1px solid var(--line); }.evidence-rail h2 { margin: 6px 0 0; color: var(--ink); font: 400 18px var(--serif); }.close-button { border: 0; background: transparent; color: var(--muted); font-size: 23px; line-height: 1; cursor: pointer; }.rail-context, .rail-state { margin: 0; padding: 13px 16px; color: var(--muted); font: 10px/1.5 var(--sans); }.reference-card { margin: 0 10px 10px; padding: 13px; border: 1px solid var(--line); background: #fff; }.reference-type { color: var(--blue); font: 9px var(--mono); }.reference-card h3 { margin: 7px 0; color: var(--ink); font-size: 12px; line-height: 1.4; }.reference-card p { margin: 0; color: var(--muted); font-size: 10px; line-height: 1.6; white-space: pre-wrap; }.reference-meta { display: flex; justify-content: space-between; gap: 8px; margin-top: 10px; color: var(--muted); font: 9px var(--mono); }.reference-meta a { display: inline-flex; align-items: center; gap: 3px; color: var(--blue); text-decoration: none; }
@media (max-width: 1120px) { .article-workspace { grid-template-columns: minmax(0, 1fr); }.evidence-rail { position: fixed; z-index: 10; inset: 0 0 0 auto; width: min(370px, 92vw); max-height: none; box-shadow: -12px 0 30px rgb(33 43 40 / 14%); } }
@media (max-width: 700px) { .article-toolbar { display: block; }.toolbar-actions { margin-top: 15px; flex-wrap: wrap; }.article-paper { margin-top: 16px; padding: 28px 18px 34px; }.article-paper footer { display: grid; }.review-strip { display: grid; gap: 4px; } }
</style>
